/** Project the existing redacted Runner row. Do not copy input text or keys. */
export function projectCaseAction(row) {
  const action = {
    index: row.index,
    type: row.action.type,
    status: row.status,
    startedAt: row.startedAt,
    endedAt: row.endedAt,
  };
  const operation = row.operation;
  if (
    operation?.kind === "browser-refresh" &&
    operation.method === "page.reload"
  ) {
    // These fields already pass through Runner redaction. Keep this list narrow
    // so new operation fields do not silently expand the case evidence surface.
    action.operation = Object.fromEntries(
      [
        "kind",
        "method",
        "pageId",
        "urlBefore",
        "waitUntil",
        "status",
        "dispatchedAt",
        "urlAfter",
        "completedAt",
        "error",
        "completion",
      ]
        .filter((key) => Object.hasOwn(operation, key))
        .map((key) => [key, operation[key]]),
    );
    if (Object.hasOwn(operation, "response"))
      action.operation.response = operation.response
        ? { url: operation.response.url, status: operation.response.status }
        : null;
  }
  return action;
}

/** Case boundaries are declared by Runner during execution, never inferred from
 * screenshots or retrofitted to old evidence. They are not test verdicts. */
export function createCaseEvidence(
  planRef,
  { save, tracing, now = () => new Date().toISOString() },
) {
  const valid =
    planRef &&
    /^[a-f0-9]{64}$/.test(planRef.answerId) &&
    /^[a-f0-9]{64}$/.test(planRef.resultSha256) &&
    Array.isArray(planRef.selectedTestIds) &&
    planRef.selectedTestIds.length > 0 &&
    planRef.selectedTestIds.every(
      (id) => typeof id === "string" && id.trim() && id.length <= 512,
    ) &&
    new Set(planRef.selectedTestIds).size === planRef.selectedTestIds.length;
  const ids = valid ? [...planRef.selectedTestIds] : [];
  const record = {
    schema: "loki.runner.case-evidence/1",
    attribution: "runner-declared-boundaries",
    planRef: valid
      ? { answerId: planRef.answerId, resultSha256: planRef.resultSha256 }
      : null,
    selectedTestIds: ids,
    cases: [],
    unassignedActions: [],
    unassignedScreenshots: [],
  };
  let active = null;
  const persist = () =>
    ids.length ? save("case-evidence.json", record) : Promise.resolve();
  const tools = ids.length
    ? [
        {
          type: "function",
          name: "test_case",
          strict: true,
          description:
            "Record the current test case boundary. Call alone before its first action and after its last observation. This records grouping only; it does not run, retry, or verify a test. Use null to end the current case. Do not replay actions to create evidence.",
          parameters: {
            type: "object",
            additionalProperties: false,
            properties: {
              testId: {
                anyOf: [{ type: "string", enum: ids }, { type: "null" }],
              },
            },
            required: ["testId"],
          },
        },
      ]
    : [];
  async function end(state) {
    if (!active) return;
    active.state = state;
    active.endedAt = now();
    active = null;
    await tracing().groupEnd();
    await persist();
  }
  return {
    tools,
    instruction: ids.length
      ? `Use test_case to group browser actions for the selected test IDs: ${JSON.stringify(ids)}. Call it alone before the first action of each case. End with testId:null after its final observation. Setup outside these boundaries stays at Run level. Boundaries do not establish pass/fail or authorize retries.`
      : "",
    async call(item) {
      let output;
      try {
        const args = JSON.parse(item.arguments);
        if (
          !args ||
          Object.keys(args).length !== 1 ||
          !Object.hasOwn(args, "testId") ||
          (args.testId !== null && !ids.includes(args.testId))
        )
          throw Error("Select a supplied test ID or null.");
        if (args.testId !== null && active)
          throw Error("End the current case before selecting another case.");
        if (args.testId === null) await end("ended");
        else {
          const occurrence =
            record.cases.filter((c) => c.testId === args.testId).length + 1;
          const title = `Test case ${args.testId} · occurrence ${occurrence}`;
          await tracing().group(title);
          active = {
            testId: args.testId,
            occurrence,
            title,
            state: "recording",
            startedAt: now(),
            endedAt: null,
            actions: [],
            screenshots: [],
          };
          record.cases.push(active);
          await persist();
        }
        output = {
          recorded: true,
          testId: active?.testId ?? null,
          occurrence: active?.occurrence ?? null,
        };
      } catch (error) {
        output = { recorded: false, error: String(error.message) };
      }
      return {
        type: "function_call_output",
        call_id: item.call_id,
        output: JSON.stringify(output),
      };
    },
    async action(row) {
      if (!ids.length) return;
      (active?.actions ?? record.unassignedActions).push(
        projectCaseAction(row),
      );
      await persist();
    },
    async screenshot(name, sha256) {
      if (!ids.length) return;
      // Reuse the screenshot the existing Runner path already saved. A provider
      // response can overwrite screen-N.png; retain only its final saved bytes.
      for (const entries of [
        record.unassignedScreenshots,
        ...record.cases.map((item) => item.screenshots),
      ]) {
        const old = entries.findIndex((item) => item.name === name);
        if (old !== -1) entries.splice(old, 1);
      }
      (active?.screenshots ?? record.unassignedScreenshots).push({
        name,
        sha256,
        capturedAt: now(),
      });
      await persist();
    },
    async close() {
      if (active) await end("interrupted");
      else await persist();
    },
  };
}
